test("bounded FIFO drops the oldest item and warns when full", () => {
  const warnings: string[] = []
  const queue = createBoundedFifo<number>({
    label: "test",
    limit: 2,
    warn: (message) => warnings.push(message),
  })

  queue.push(1)
  queue.push(2)
  queue.push(3)

  assert.deepEqual(queue.drain(), [2, 3])
  assert.equal(warnings.length, 1)
})

test("accepts only generated UUID v4 correlation identifiers", () => {
  assert.throws(
    () =>
      createAppPerformanceEvent({
        routeGroup: "routine",
        operation: "proxy_access",
        outcome: "success",
        durationMs: 1,
        correlationId: "request-correlation-id",
      }),
    /correlationId/,
  )
})

